export default async function start({ acknowledgeTicketId }, ctx) {
  const s = (await ctx.state.get("zendesk-hubspot")) ?? {
    cursor: null,
    processed: {},
    pending: null,
    seen: [],
  };
  if (s.pending) {
    if (String(acknowledgeTicketId) !== String(s.pending.id))
      throw Error(
        "Inspect and complete pending Zendesk ticket " + s.pending.id + " at " + s.pending.stage,
      );
    s.processed[s.pending.id] = s.pending.updated_at;
    s.pending = null;
    await ctx.state.set("zendesk-hubspot", s);
  }
  if (!s.startTime) {
    s.startTime = Math.floor(Date.now() / 1000) - 120;
    await ctx.state.set("zendesk-hubspot", s);
  }
  return {
    query: s.cursor
      ? { cursor: s.cursor, per_page: 100 }
      : { start_time: s.startTime, per_page: 100 },
  };
}

