export default async function query(_input, ctx) {
  const s = await ctx.state.get("zendesk-hubspot");
  if (!s || s.pending || !s.startTime) throw Error("Sync state is not ready");
  return {
    query: s.cursor
      ? { cursor: s.cursor, per_page: 100 }
      : { start_time: s.startTime, per_page: 100 },
  };
}

