export default async function next({ page, previousState }, ctx) {
  if (
    !page ||
    !Array.isArray(page.tickets) ||
    typeof page.after_cursor !== "string" ||
    typeof page.end_of_stream !== "boolean"
  )
    throw Error("Invalid Zendesk incremental page");
  const s = await ctx.state.get("zendesk-hubspot");
  if (!s || s.pending) throw Error("A ticket is pending reconciliation");
  const pageKey = s.cursor ?? String(s.startTime);
  let i = previousState?.pageKey === pageKey ? previousState.index : 0;
  while (i < page.tickets.length) {
    const t = page.tickets[i++];
    if (
      !Number.isSafeInteger(t.id) ||
      !Number.isSafeInteger(t.requester_id) ||
      typeof t.updated_at !== "string"
    )
      throw Error("Ticket missing identity");
    if (s.processed[String(t.id)] === t.updated_at) continue;
    s.pending = {
      id: t.id,
      updated_at: t.updated_at,
      stage: t.external_id ? "update HubSpot ticket" : "upsert HubSpot contact",
    };
    await ctx.state.set("zendesk-hubspot", s);
    return {
      state: { index: i, pageKey },
      more: true,
      fetchNext: false,
      query: {},
      ticket: t,
      ticketId: t.id,
      existing: !!t.external_id,
      userId: t.requester_id,
      endpoint: t.external_id
        ? "https://api.hubapi.com/crm/v3/objects/tickets/" +
          encodeURIComponent(String(t.external_id))
        : "https://api.hubapi.com/crm/v3/objects/tickets",
      ticketBody: {
        properties: { subject: t.raw_subject ?? t.subject ?? "", content: t.description ?? "" },
      },
    };
  }
  if (!page.end_of_stream && (s.seen.includes(page.after_cursor) || s.cursor === page.after_cursor))
    throw Error("Repeated Zendesk cursor");
  s.cursor = page.after_cursor;
  s.processed = {};
  s.seen = page.end_of_stream ? [] : [...s.seen, page.after_cursor];
  await ctx.state.set("zendesk-hubspot", s);
  return {
    state: { index: i, pageKey },
    more: false,
    fetchNext: !page.end_of_stream,
    query: { cursor: page.after_cursor, per_page: 100 },
    ticket: {},
    ticketId: 1,
    existing: false,
    userId: 1,
    endpoint: "https://api.hubapi.com/crm/v3/objects/tickets",
    ticketBody: {},
  };
}

