export default async function finish({ ticket, result, expect }, ctx) {
  const ok =
    expect === "hubspot"
      ? typeof result?.id === "string"
      : expect === "zendesk"
        ? result?.id === ticket.id
        : false;
  if (!ok) throw Error("Ticket update not confirmed");
  const s = await ctx.state.get("zendesk-hubspot");
  if (s?.pending?.id !== ticket.id) throw Error("Pending ticket mismatch");
  s.processed[String(ticket.id)] = ticket.updated_at;
  s.pending = null;
  await ctx.state.set("zendesk-hubspot", s);
  return { done: true };
}

