export default function contact({ user, ticket }) {
  if (user?.id !== ticket.requester_id || typeof user.email !== "string" || !user.email)
    throw Error("Requester has no email or does not match ticket");
  return {
    body: { inputs: [{ id: user.email, idProperty: "email", properties: { email: user.email } }] },
    userId: user.id,
  };
}

