export default async function stage({ ticket, result, expect, nextStage }, ctx) {
  const ok =
    expect === "contact"
      ? typeof result?.results?.[0]?.id === "string"
      : expect === "ticket"
        ? typeof result?.id === "string"
        : expect === "zendesk"
          ? result?.user?.id === ticket.requester_id
          : expect === "association"
            ? Number.isInteger(result) && result >= 200 && result < 300
            : false;
  if (!ok) throw Error("Previous service write not confirmed");
  const s = await ctx.state.get("zendesk-hubspot");
  if (s?.pending?.id !== ticket.id) throw Error("Pending ticket mismatch");
  const contactId = expect === "contact" ? result.results[0].id : (s.pending.contactId ?? ""),
    ticketId = expect === "ticket" ? result.id : (s.pending.ticketId ?? "");
  s.pending = { ...s.pending, stage: nextStage, contactId, ticketId };
  await ctx.state.set("zendesk-hubspot", s);
  return { contactId: contactId || "unused", ticketId: ticketId || "unused" };
}

