export default function prepare({ userId, contactId }) {
  if (!Number.isSafeInteger(userId) || !contactId || contactId === "unused")
    throw Error("Missing requester or contact ID");
  return {
    endpoint: "/api/v2/users/" + userId + ".json",
    body: { user: { external_id: contactId } },
  };
}

