export default function prepare({ ticket, pipelineId, stageId }) {
  if (!pipelineId || !stageId) throw Error("Configure HubSpot ticket pipeline and stage");
  return {
    body: {
      properties: {
        subject: ticket.raw_subject ?? ticket.subject ?? "",
        content: ticket.description ?? "",
        hs_pipeline: pipelineId,
        hs_pipeline_stage: stageId,
      },
    },
  };
}

