export default function prepare({ ticketId, contactId }) {
  if (!ticketId || !contactId || ticketId === "unused" || contactId === "unused")
    throw Error("Missing ticket or contact ID");
  return {
    url:
      "https://api.hubapi.com/crm/v4/objects/tickets/" +
      encodeURIComponent(ticketId) +
      "/associations/default/contacts/" +
      encodeURIComponent(contactId),
  };
}

